export function getProductLink(urlKey, sku) {
  if (!urlKey) {
    console.warn('getProductLink: urlKey is missing or empty', { urlKey, sku });
  }
  if (!sku) {
    console.warn('getProductLink: sku is missing or empty', { urlKey, sku });
